WITH kept_keys AS (SELECT id, txn_type FROM transactions INTERSECT SELECT id, txn_type FROM transactions WHERE amount IS NOT NULL), verified AS (SELECT s.* FROM transactions s JOIN kept_keys k ON s.id = k.id AND s.txn_type = k.txn_type) SELECT DATE_TRUNC('WEEK', txn_time) AS week_start, CASE WHEN amount >= 3000 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, COUNT(*) AS row_count, COUNT_IF(txn_type = 'DEBIT') AS debit_events, COUNT_IF(txn_type = 'FEE') AS fee_events, MIN(txn_time) AS started_at, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('WEEK', txn_time) ORDER BY COUNT_IF(txn_type = 'FEE') DESC) AS fee_events_dense_rank FROM verified GROUP BY DATE_TRUNC('WEEK', txn_time), CASE WHEN amount >= 3000 THEN 'HIGH' ELSE 'LOW' END ORDER BY row_count DESC NULLS FIRST
